<?php
namespace App\Controllers\Api;use App\Support\App;use App\Services\OrderService;
final class DhruController{private function auth():?array{$key=$_REQUEST['key']??$_REQUEST['apikey']??'';if(!$key)return null;$hash=hash('sha256',$key);$q=App::db()->prepare('SELECT u.* FROM api_keys a JOIN users u ON u.id=a.user_id WHERE a.key_hash=? AND a.is_active=1');$q->execute([$hash]);return $q->fetch()?:null;}public function handle():never{$u=$this->auth();header('Content-Type: text/xml; charset=utf-8');if(!$u){echo '<ERROR><MESSAGE>Authentication failed</MESSAGE></ERROR>';exit;}$action=strtolower((string)($_REQUEST['action']??''));if($action==='accountinfo'){echo '<ACCOUNTINFO><BALANCE>'.htmlspecialchars((string)$u['balance']).'</BALANCE></ACCOUNTINFO>';exit;}if($action==='placeimeiorder'){$imei=preg_replace('/\D/','',(string)($_REQUEST['imei']??''));$pid=(int)($_REQUEST['service']??0);try{$o=(new OrderService())->create((int)$u['id'],$pid,$imei);echo '<ORDER><ID>'.$o['order_number'].'</ID><STATUS>'.$o['status'].'</STATUS></ORDER>';}catch(\Throwable $e){echo '<ERROR><MESSAGE>'.htmlspecialchars($e->getMessage()).'</MESSAGE></ERROR>';}exit;}echo '<ERROR><MESSAGE>Unsupported action</MESSAGE></ERROR>';exit;}}
